1: /**
2:  * QuickJS WASM - A snapshotable JavaScript runtime via WebAssembly.
3:  *
4:  * Provides a clean JavaScript API for running sandboxed JS code in a QuickJS
5:  * VM compiled to WASM. The key differentiator is the ability to snapshot the
6:  * entire VM state (including pending promises) and restore it in a fresh
7:  * WASM instance.
8:  */
9: 
10: import { createWasiShim, type WasiOptions } from './wasi-shim.js';
11: import {
12:   loadExtension,
13:   initExtension,
14:   restoreExtensions,
15:   type ExtensionDescriptor,
16:   type LoadedExtension,
17:   type WasiImports,
18: } from './extensions.js';
19: import { VERSION } from './version.js';
20: 
21: // ---- Public types ----
22: 
23: export type HostFunction = (this: JSValueHandle, ...args: JSValueHandle[]) => JSValueHandle;
24: 
25: /** Property descriptor flags for `defineProp()`. */
26: export interface JSPropertyDescriptor {
27:   writable?: boolean;
28:   enumerable?: boolean;
29:   configurable?: boolean;
30: }
31: 
32: export type { WasiOptions };
33: export type { ExtensionDescriptor, LoadedExtension, DylinkInfo, WasiImports } from './extensions.js';
34: 
35: /**
36:  * Flags for `evalCode()`, matching the QuickJS `JS_EVAL_*` constants.
37:  */
38: export const EvalFlags = {
39:   /** Global script mode (default). */
40:   TYPE_GLOBAL: 0 as const,
41:   /** Module mode. */
42:   TYPE_MODULE: (1 << 0) as 1,
43:   /** Force strict mode. */
44:   STRICT: (1 << 3) as 8,
45:   /** Compile only — do not execute. */
46:   COMPILE_ONLY: (1 << 5) as 32,
47:   /** Omit stack frames before this eval from Error backtraces. */
48:   BACKTRACE_BARRIER: (1 << 6) as 64,
49:   /**
50:    * Allow top-level `await` in global scripts. When used, `evalCode()`
51:    * returns a handle to a Promise that resolves to the completion value.
52:    * Use together with `executePendingJobs()` and `resolvePromise()`.
53:    */
54:   ASYNC: (1 << 7) as 128,
55: } as const;
56: 
57: /**
58:  * Flags for `vm.compile()` controlling what is included in the bytecode output.
59:  * These can be combined with bitwise OR.
60:  */
61: export const CompileFlags = {
62:   /** Strip source code from the bytecode (smaller output, no source in errors). */
63:   STRIP_SOURCE: (1 << 4) as 16,
64:   /** Strip debug information (line numbers, etc.) from the bytecode. */
65:   STRIP_DEBUG: (1 << 5) as 32,
66: } as const;
67: 
68: /**
69:  * Intrinsic flags for `QuickJSOptions.intrinsics` controlling which
70:  * built-in JavaScript features are available in the VM.
71:  *
72:  * By default all intrinsics are enabled. Pass a bitmask of these flags
73:  * to create a minimal context — for example, omit `Intrinsics.EVAL` to
74:  * prevent `eval()` usage, or omit `Intrinsics.PROXY` to disallow `Proxy`.
75:  *
76:  * `BaseObjects` (Object, Array, Number, String, Boolean, Error, etc.)
77:  * is always included and cannot be disabled.
78:  */
79: export const Intrinsics = {
80:   /** `Date` constructor and prototype methods. */
81:   DATE: (1 << 0) as 1,
82:   /** `eval()` and `Function()` constructor. */
83:   EVAL: (1 << 1) as 2,
84:   /** `RegExp` constructor, prototype methods, and regex literals. */
85:   REGEXP: (1 << 2) as 4,
86:   /** `JSON.parse()` and `JSON.stringify()`. */
87:   JSON: (1 << 3) as 8,
88:   /** `Proxy` and `Reflect`. */
89:   PROXY: (1 << 4) as 16,
90:   /** `Map`, `Set`, `WeakMap`, `WeakSet`. */
91:   MAP_SET: (1 << 5) as 32,
92:   /** `ArrayBuffer`, `TypedArray` variants, `DataView`. */
93:   TYPED_ARRAYS: (1 << 6) as 64,
94:   /** `Promise`, `async`/`await`. */
95:   PROMISE: (1 << 7) as 128,
96:   /** `BigInt`. Note: BigInt is part of BaseObjects in quickjs-ng and cannot be fully removed. */
97:   BIG_INT: (1 << 8) as 256,
98:   /** `WeakRef` and `FinalizationRegistry`. */
99:   WEAK_REF: (1 << 9) as 512,
100:   /** `performance.now()`. */
101:   PERFORMANCE: (1 << 10) as 1024,
102:   /** `DOMException` class. */
103:   DOM_EXCEPTION: (1 << 11) as 2048,
104:   /**
105:    * `atob()` and `btoa()` global functions. Also pulls in `DOMException` as
106:    * a dependency (errors thrown by these functions are `DOMException`s).
107:    */
108:   ATOB_BTOA: (1 << 12) as 4096,
109:   /** All intrinsics enabled (default). */
110:   ALL: 0xFFFFFFFF,
111: } as const;
112: 
113: /** Memory usage statistics from the QuickJS runtime. */
114: export interface MemoryUsage {
115:   /** Total bytes allocated via malloc */
116:   mallocSize: number;
117:   /** Current malloc limit (0 for unlimited) */
118:   mallocLimit: number;
119:   /** Total memory used (including overhead) */
120:   memoryUsedSize: number;
121:   /** Number of malloc calls */
122:   mallocCount: number;
123:   /** Number of memory-using objects */
124:   memoryUsedCount: number;
125:   /** Number of atoms */
126:   atomCount: number;
127:   /** Atom memory size */
128:   atomSize: number;
129:   /** Number of strings */
130:   strCount: number;
131:   /** String memory size */
132:   strSize: number;
133:   /** Number of objects */
134:   objCount: number;
135:   /** Object memory size */
136:   objSize: number;
137:   /** Number of properties */
138:   propCount: number;
139:   /** Property memory size */
140:   propSize: number;
141:   /** Number of shapes */
142:   shapeCount: number;
143:   /** Shape memory size */
144:   shapeSize: number;
145:   /** Number of JS functions */
146:   jsFuncCount: number;
147:   /** JS function memory size */
148:   jsFuncSize: number;
149:   /** JS function code size */
150:   jsFuncCodeSize: number;
151:   /** Number of PC-to-line mappings */
152:   jsFuncPc2lineCount: number;
153:   /** PC-to-line mapping memory size */
154:   jsFuncPc2lineSize: number;
155:   /** Number of C functions */
156:   cFuncCount: number;
157:   /** Number of arrays */
158:   arrayCount: number;
159:   /** Number of fast arrays */
160:   fastArrayCount: number;
161:   /** Number of fast array elements */
162:   fastArrayElements: number;
163:   /** Number of binary objects (ArrayBuffer, etc.) */
164:   binaryObjectCount: number;
165:   /** Binary object memory size */
166:   binaryObjectSize: number;
167: }
