410: // ---- Snapshot format ----
411: 
412: /** Metadata about an extension saved in a snapshot */
413: export interface SnapshotExtension {
414:   name: string;
415:   memoryBase: number;
416:   tableBase: number;
417:   initFn: string;
418: }
419: 
420: export interface Snapshot {
421:   /** The raw WASM linear memory contents */
422:   memory: Uint8Array;
423:   /** The stack pointer value at snapshot time */
424:   stackPointer: number;
425:   /** Pointer to JSRuntime in the WASM memory */
426:   runtimePtr: number;
427:   /** Pointer to JSContext in the WASM memory */
428:   contextPtr: number;
429:   /** Metadata about loaded extensions (empty if none) */
430:   extensions: SnapshotExtension[];
431: }
432: 
433: // ---- Snapshot serialization ----
434: 
435: /** Magic bytes: "QJSS" (QuickJS Snapshot) */
436: const SNAPSHOT_MAGIC = 0x514A5353;
437: /** Current serialization format version (2 = added extension metadata) */
438: const SNAPSHOT_VERSION = 2;
439: /**
440:  * Header layout (version 2):
441:  *   0-3:   Magic "QJSS" (u32 big-endian)
442:  *   4:     Version (u8)
443:  *   5-7:   Reserved (zero)
444:  *   8-11:  Memory size in bytes (u32 little-endian)
445:  *   12-15: Stack pointer (u32 little-endian)
446:  *   16-19: Runtime pointer (u32 little-endian)
447:  *   20-23: Context pointer (u32 little-endian)
448:  *   24-27: Extension count (u32 little-endian)
449:  *   28+:   Extension entries (variable length):
450:  *          nameLen(u32) + name(utf8) + memoryBase(u32) + tableBase(u32) + initFnLen(u32) + initFn(utf8)
451:  *   N+:    Memory data (N = memory size from offset 8)
452:  *
453:  * Version 1 (legacy): no extension metadata, memory starts at offset 24.
454:  */
455: const SNAPSHOT_HEADER_SIZE = 24;
456: 
457: // ---- Deferred promise type ----
458: 
459: export interface Deferred {
460:   /** Handle to the QuickJS promise object */
461:   handle: JSValueHandle;
462:   /** A host-side Promise that resolves when the QuickJS promise settles */
463:   settled: Promise<void>;
464:   /** Resolve the QuickJS promise with a value */
465:   resolve(value: JSValueHandle): void;
466:   /** Reject the QuickJS promise with a value */
467:   reject(value: JSValueHandle): void;
468: }
