470: // ---- QuickJS VM ----
471: 
472: export class QuickJS {
473:   private exports: QuickJSExports;
474:   private module: WebAssembly.Module;
475:   private instance: WebAssembly.Instance;
476:   private encoder = new TextEncoder();
477:   private decoder = new TextDecoder();
478:   private disposed = false;
479: 
480:   /** Registry of host callbacks, keyed by function name */
481:   private hostCallbacks = new Map<string, HostFunction>();
482:   /** Counter for internal-only callbacks (e.g. promise settle handlers) */
483:   private nextInternalId = 1;
484:   private interruptHandler: (() => boolean) | null = null;
