682:   // ---- Snapshot serialization ----
683: 
684:   /**
685:    * Serialize a snapshot to a binary buffer for persistent storage.
686:    *
687:    * The format includes a versioned header followed by the raw memory.
688:    * Apply your own compression (gzip, zstd, etc.) on top for smaller
689:    * storage — the memory compresses very well due to large zero regions.
690:    *
691:    * Format (version 1):
692:    * ```
693:    * Offset  Size  Field
694:    * 0       4     Magic: "QJSS" (0x514A5353, big-endian)
695:    * 4       1     Version: 1
696:    * 5       3     Reserved (zero)
697:    * 8       4     Memory size in bytes (u32 little-endian)
698:    * 12      4     Stack pointer (u32 little-endian)
699:    * 16      4     Runtime pointer (u32 little-endian)
700:    * 20      4     Context pointer (u32 little-endian)
701:    * 24      N     Memory data (N = memory size from offset 8)
702:    * ```
703:    */
704:   static serializeSnapshot(snapshot: Snapshot): Uint8Array {
705:     const textEncoder = new TextEncoder();
706: 
707:     // Calculate extension metadata size
708:     let extMetaSize = 4; // extCount (u32)
709:     const extEncodedNames: Uint8Array[] = [];
710:     const extEncodedInitFns: Uint8Array[] = [];
711:     for (const ext of snapshot.extensions) {
712:       const nameBytes = textEncoder.encode(ext.name);
713:       const initFnBytes = textEncoder.encode(ext.initFn);
714:       extEncodedNames.push(nameBytes);
715:       extEncodedInitFns.push(initFnBytes);
716:       extMetaSize += 4 + nameBytes.length + 4 + 4 + 4 + initFnBytes.length;
717:     }
718: 
719:     const totalSize = SNAPSHOT_HEADER_SIZE + extMetaSize + snapshot.memory.byteLength;
720: 
721:     const buffer = new ArrayBuffer(totalSize);
722:     const view = new DataView(buffer);
723:     const bytes = new Uint8Array(buffer);
724: 
725:     // Header
726:     view.setUint32(0, SNAPSHOT_MAGIC, false); // big-endian for readability in hex
727:     view.setUint8(4, SNAPSHOT_VERSION);
728:     // bytes 5-7 are reserved (already zero)
729:     view.setUint32(8, snapshot.memory.byteLength, true);
730:     view.setUint32(12, snapshot.stackPointer, true);
731:     view.setUint32(16, snapshot.runtimePtr, true);
732:     view.setUint32(20, snapshot.contextPtr, true);
733: 
734:     // Extension metadata (version 2)
735:     let offset = SNAPSHOT_HEADER_SIZE;
736:     view.setUint32(offset, snapshot.extensions.length, true);
737:     offset += 4;
738: 
739:     for (let i = 0; i < snapshot.extensions.length; i++) {
740:       const ext = snapshot.extensions[i];
741:       const nameBytes = extEncodedNames[i];
742:       const initFnBytes = extEncodedInitFns[i];
743: 
744:       view.setUint32(offset, nameBytes.length, true);
745:       offset += 4;
746:       bytes.set(nameBytes, offset);
747:       offset += nameBytes.length;
748:       view.setUint32(offset, ext.memoryBase, true);
749:       offset += 4;
750:       view.setUint32(offset, ext.tableBase, true);
751:       offset += 4;
752:       view.setUint32(offset, initFnBytes.length, true);
753:       offset += 4;
754:       bytes.set(initFnBytes, offset);
755:       offset += initFnBytes.length;
756:     }
757: 
758:     // Memory data
759:     bytes.set(snapshot.memory, offset);
760: 
761:     return bytes;
762:   }
763: 
764:   /**
765:    * Deserialize a snapshot from a binary buffer produced by `serializeSnapshot()`.
766:    */
767:   static deserializeSnapshot(data: Uint8Array): Snapshot {
768:     if (data.length < SNAPSHOT_HEADER_SIZE) {
769:       throw new Error('Invalid snapshot: too small');
770:     }
771: 
772:     const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
773: 
774:     // Validate magic
775:     const magic = view.getUint32(0, false);
776:     if (magic !== SNAPSHOT_MAGIC) {
777:       throw new Error(`Invalid snapshot: bad magic (expected 0x${SNAPSHOT_MAGIC.toString(16)}, got 0x${magic.toString(16)})`);
778:     }
779: 
780:     // Validate version
781:     const version = view.getUint8(4);
782:     if (version !== SNAPSHOT_VERSION && version !== 1) {
783:       throw new Error(`Unsupported snapshot version: ${version} (expected ${SNAPSHOT_VERSION})`);
784:     }
785: 
786:     const memorySize = view.getUint32(8, true);
787:     const stackPointer = view.getUint32(12, true);
788:     const runtimePtr = view.getUint32(16, true);
789:     const contextPtr = view.getUint32(20, true);
790: 
791:     let extensions: SnapshotExtension[] = [];
792:     let memoryOffset = SNAPSHOT_HEADER_SIZE;
793: 
794:     if (version >= 2) {
795:       // Version 2 adds extension metadata between the header and the memory data
796:       const extCount = view.getUint32(24, true);
797:       let offset = 28;
798:       const textDecoder = new TextDecoder();
799: 
800:       for (let i = 0; i < extCount; i++) {
801:         // name length (u32) + name (utf8) + memoryBase (u32) + tableBase (u32) + initFn length (u32) + initFn (utf8)
802:         const nameLen = view.getUint32(offset, true);
803:         offset += 4;
804:         const name = textDecoder.decode(data.slice(offset, offset + nameLen));
805:         offset += nameLen;
806:         const memBase = view.getUint32(offset, true);
807:         offset += 4;
808:         const tblBase = view.getUint32(offset, true);
809:         offset += 4;
810:         const initFnLen = view.getUint32(offset, true);
811:         offset += 4;
812:         const initFn = textDecoder.decode(data.slice(offset, offset + initFnLen));
813:         offset += initFnLen;
814:         extensions.push({ name, memoryBase: memBase, tableBase: tblBase, initFn });
815:       }
816:       memoryOffset = offset;
817:     }
818: 
819:     const expectedSize = memoryOffset + memorySize;
820:     if (data.length < expectedSize) {
821:       throw new Error(`Invalid snapshot: expected ${expectedSize} bytes, got ${data.length}`);
822:     }
823: 
824:     const memory = data.slice(memoryOffset, memoryOffset + memorySize);
825: 
826:     return { memory, stackPointer, runtimePtr, contextPtr, extensions };
827:   }
