831:   private static normalizeOptions(options?: QuickJSOptions | BufferSource | WebAssembly.Module): QuickJSOptions {
832:     if (!options) {
833:       // resolveModule() will throw a helpful error.
834:       return { wasm: undefined as unknown as BufferSource };
835:     }
836:     if (options instanceof WebAssembly.Module) return { wasm: options };
837:     if (typeof options === 'object' && ('wasm' in options || 'wasi' in options || 'memoryLimit' in options || 'interruptHandler' in options || 'onUnhandledRejection' in options || 'moduleLoader' in options || 'intrinsics' in options || 'extensions' in options || 'timezoneOffset' in options)) return options as QuickJSOptions;
838:     // BufferSource (ArrayBuffer or ArrayBufferView)
839:     return { wasm: options as BufferSource };
840:   }
841: 
842:   private static applyLimits(vm: QuickJS, opts: QuickJSOptions): void {
843:     if (opts.memoryLimit !== undefined) {
844:       vm.exports.qjs_set_memory_limit(opts.memoryLimit);
845:     }
846:     if (opts.interruptHandler) {
847:       vm.interruptHandler = opts.interruptHandler;
848:       vm.exports.qjs_set_interrupt_handler(1);
849:     }
850:     if (opts.onUnhandledRejection) {
851:       vm.unhandledRejectionHandler = opts.onUnhandledRejection;
852:       vm.exports.qjs_set_promise_rejection_handler(1);
853:     }
854:     if (opts.moduleLoader) {
855:       vm.moduleLoadHandler = opts.moduleLoader.load;
856:       vm.moduleNormalizeHandler = opts.moduleLoader.normalize ?? null;
857:       vm.exports.qjs_set_module_loader(1);
858:     }
859:     // Configure timezone handler.
860:     // The internal handler always returns the UTC offset in *seconds*
861:     // (positive east of UTC), which is what libc's __secs_to_zone expects.
862:     const tz = opts.timezoneOffset;
863:     if (typeof tz === 'function') {
864:       // User callback returns minutes (getTimezoneOffset convention:
865:       // positive west of UTC). Convert to seconds with sign flip.
866:       vm.timezoneOffsetHandler = (timeSecs: number) => -tz(timeSecs) * 60;
867:     } else if (typeof tz === 'number') {
868:       // Fixed offset in minutes, convert to seconds with sign flip.
869:       const offsetSecs = -tz * 60;
870:       vm.timezoneOffsetHandler = () => offsetSecs;
871:     } else {
872:       // 'host' (default): use the host's timezone
873:       vm.timezoneOffsetHandler = (timeSecs: number) => {
874:         return -new Date(timeSecs * 1000).getTimezoneOffset() * 60;
875:       };
876:     }
877:   }
