879:   private static async resolveModule(wasmInput?: BufferSource | WebAssembly.Module): Promise<WebAssembly.Module> {
880:     if (wasmInput instanceof WebAssembly.Module) {
881:       return wasmInput;
882:     }
883:     if (wasmInput) {
884:       return WebAssembly.compile(wasmInput);
885:     }
886:     throw new TypeError(
887:       'QuickJS: `wasm` option is required. Provide WASM bytes or a compiled ' +
888:       '`WebAssembly.Module`. The binary is shipped at `quickjs-wasi/quickjs.wasm` ' +
889:       'and can be loaded via your environment\'s preferred mechanism (e.g. ' +
890:       "`fetch()`, `node:fs/promises`, or a bundler import like Vite's `?url`).",
891:     );
892:   }
