1035:   // ---- String helpers ----
1036: 
1037:   /** Write a JS string into WASM memory, returning the pointer. Caller must free. */
1038:   private writeString(str: string): { ptr: number; len: number } {
1039:     const encoded = this.encoder.encode(str);
1040:     const ptr = this.exports.wasm_malloc(encoded.length + 1);
1041:     if (ptr === 0) throw new Error('wasm_malloc failed');
1042:     const mem = new Uint8Array(this.exports.memory.buffer);
1043:     mem.set(encoded, ptr);
1044:     mem[ptr + encoded.length] = 0;
1045:     return { ptr, len: encoded.length };
