1: /**
2:  * WASM Dynamic Linking - Extension Loader
3:  *
4:  * Loads WASM shared libraries (.so) compiled with wasi-sdk as extensions
5:  * for the QuickJS WASM runtime. Extensions can call QuickJS C API functions
6:  * directly through dynamic linking (shared memory + symbol resolution).
7:  *
8:  * Key concepts:
9:  * - Extensions are WASM shared libraries with a `dylink.0` custom section
10:  * - They share linear memory and the indirect function table with the main module
11:  * - Symbol imports (env.*) are resolved against the main module's exports
12:  * - Each extension gets a unique __memory_base and __table_base
13:  * - Extensions export an init function (e.g., `qjs_ext_url_init`)
14:  */
15: 
16: const decoder = new TextDecoder();
17: 
18: /**
19:  * Parse a null-terminated "key=value\nkey=value" string from WASM memory
20:  * into a Record<string, string>. Used to read version info from extensions.
21:  */
22: function parseVersionString(memory: WebAssembly.Memory, ptr: number): Record<string, string> {
23:   const mem = new Uint8Array(memory.buffer);
24:   let end = ptr;
25:   while (mem[end] !== 0) end++;
26:   if (end === ptr) return {};
27:   const str = decoder.decode(mem.slice(ptr, end));
28:   const result: Record<string, string> = {};
29:   for (const line of str.split('\n')) {
30:     const eq = line.indexOf('=');
31:     if (eq > 0) {
32:       result[line.slice(0, eq)] = line.slice(eq + 1);
33:     }
34:   }
35:   return result;
36: }
