38: /**
39:  * Check if an extension exports a versions function and parse the result.
40:  */
41: function extractExtensionVersions(
42:   ext: LoadedExtension,
43:   memory: WebAssembly.Memory,
44: ): Record<string, string> | undefined {
45:   const versionsFnName = `qjs_ext_${ext.name.replace(/-/g, '_')}_versions`;
46:   const versionsFn = ext.instance.exports[versionsFnName];
47:   if (typeof versionsFn !== 'function') return undefined;
48:   const ptr = (versionsFn as Function)() as number;
49:   if (ptr === 0) return undefined;
50:   return parseVersionString(memory, ptr);
51: }
