131: /** Parse the dylink.0 custom section from a WASM module */
132: export function parseDylink(module: WebAssembly.Module): DylinkInfo | null {
133:   const sections = WebAssembly.Module.customSections(module, 'dylink.0');
134:   if (sections.length === 0) return null;
135: 
136:   const bytes = new Uint8Array(sections[0]);
137:   const offset = { value: 0 };
138: 
139:   const info: DylinkInfo = {
140:     memorySize: 0,
141:     memoryAlignment: 0,
142:     tableSize: 0,
143:     tableAlignment: 0,
144:     needed: [],
145:   };
146: 
147:   while (offset.value < bytes.length) {
148:     const subsectionType = readULEB128(bytes, offset);
149:     const subsectionSize = readULEB128(bytes, offset);
150:     const subsectionEnd = offset.value + subsectionSize;
151: 
152:     if (subsectionType === 1) {
153:       // WASM_DYLINK_MEM_INFO
154:       info.memorySize = readULEB128(bytes, offset);
155:       info.memoryAlignment = readULEB128(bytes, offset);
156:       info.tableSize = readULEB128(bytes, offset);
157:       info.tableAlignment = readULEB128(bytes, offset);
158:     } else if (subsectionType === 2) {
159:       // WASM_DYLINK_NEEDED
160:       const count = readULEB128(bytes, offset);
161:       for (let i = 0; i < count; i++) {
162:         const len = readULEB128(bytes, offset);
163:         const name = new TextDecoder().decode(
164:           bytes.slice(offset.value, offset.value + len)
165:         );
166:         offset.value += len;
167:         info.needed.push(name);
168:       }
169:     }
170: 
171:     offset.value = subsectionEnd;
172:   }
173: 
174:   return info;
175: }
