64:  * (e.g. resolve "./foo" relative to a base module name).
65:  *
66:  * Returns a pointer to a null-terminated string in WASM memory (allocated
67:  * with malloc). The caller frees it with js_free(). Returns NULL on error.
68:  */
69: __attribute__((import_module("env"), import_name("host_module_normalize")))
70: extern char *host_module_normalize(const char *base_name, const char *name);
71: 
72: /*
73:  * Imported from the host environment. Called to load module source code.
74:  * The host writes the source code into WASM memory and returns a pointer
75:  * to a null-terminated source string (allocated with malloc).
76:  * The caller frees it. Returns NULL on error.
77:  */
78: __attribute__((import_module("env"), import_name("host_module_load")))
79: extern char *host_module_load(const char *module_name, size_t *out_len);
80: 
81: /*
82:  * Module normalizer trampoline: dispatches to the host_module_normalize import.
83:  * Returns a js_malloc'd string with the normalized module name.
84:  */
85: static char *module_normalizer_trampoline(JSContext *ctx,
86:                                            const char *module_base_name,
87:                                            const char *module_name, void *opaque)
88: {
89:     (void)ctx;
90:     (void)opaque;
91:     char *result = host_module_normalize(module_base_name, module_name);
92:     if (!result) {
93:         JS_ThrowReferenceError(ctx, "could not normalize module '%s'", module_name);
94:         return NULL;
95:     }
96:     /* The host allocated with malloc; QuickJS expects js_malloc'd memory.
97:        Since we're using the same allocator (wasi libc malloc), this is fine. */
98:     return result;
99: }
100: 
101: /*
102:  * Module loader trampoline: dispatches to the host_module_load import.
103:  * Receives source code from the host, compiles it, and returns the JSModuleDef.
104:  */
105: static JSModuleDef *module_loader_trampoline(JSContext *ctx,
106:                                               const char *module_name, void *opaque)
107: {
108:     (void)opaque;
109:     size_t source_len = 0;
110:     char *source = host_module_load(module_name, &source_len);
111:     if (!source) {
112:         JS_ThrowReferenceError(ctx, "could not load module '%s'", module_name);
113:         return NULL;
114:     }
115: 
116:     /* Compile the module source (COMPILE_ONLY so it returns the module def) */
117:     JSValue func_val = JS_Eval(ctx, source, source_len, module_name,
118:                                 JS_EVAL_TYPE_MODULE | JS_EVAL_FLAG_COMPILE_ONLY);
119:     free(source);
120: 
121:     if (JS_IsException(func_val)) {
122:         return NULL;
123:     }
124: 
125:     /* Extract the JSModuleDef from the compiled module function */
126:     JSModuleDef *m = (JSModuleDef *)JS_VALUE_GET_PTR(func_val);
127:     /* Don't free func_val — the module is owned by the runtime */
128:     return m;
129: }
130: 
131: /*
132:  * Imported from the host environment. Called when a promise is rejected
133:  * without a handler, or when a handler is attached to a previously
134:  * unhandled rejection.
135:  *   promise_ptr - pointer to heap-allocated JSValue for the promise
136:  *   reason_ptr  - pointer to heap-allocated JSValue for the rejection reason
137:  *   is_handled  - 1 if a handler was just attached, 0 if newly unhandled
138:  */
139: __attribute__((import_module("env"), import_name("host_promise_rejection")))
140: extern void host_promise_rejection(JSValue *promise_ptr, JSValue *reason_ptr, int is_handled);
141: 
142: /*
143:  * Promise rejection tracker trampoline: heap-allocates the promise and reason
144:  * values and dispatches to the host_promise_rejection import.
145:  */
146: static void promise_rejection_trampoline(JSContext *ctx, JSValueConst promise,
147:                                           JSValueConst reason,
148:                                           bool is_handled, void *opaque)
149: {
150:     (void)opaque;
151:     JSValue *promise_ptr = jsvalue_to_heap(JS_DupValue(ctx, promise));
152:     JSValue *reason_ptr = jsvalue_to_heap(JS_DupValue(ctx, reason));
153:     host_promise_rejection(promise_ptr, reason_ptr, is_handled ? 1 : 0);
154:     /* The host is responsible for freeing these via qjs_free_value */
155: }
156: 
157: /*
158:  * Trampoline: a JSCFunctionData callback that dispatches to the host.
159:  * The function name is stored in func_data[0] as a JS string.
160:  */
161: static JSValue host_callback_trampoline(JSContext *ctx, JSValueConst this_val,
162:                                          int argc, JSValueConst *argv,
163:                                          int magic, JSValueConst *func_data)
164: {
165:     (void)magic;
166: 
167:     /* Extract the function name from func_data[0] */
168:     size_t name_len;
169:     const char *name = JS_ToCStringLen(ctx, &name_len, func_data[0]);
170: 
171:     /* Heap-allocate this_val for the host */
172:     JSValue *this_ptr = jsvalue_to_heap(JS_DupValue(ctx, this_val));
173: 
174:     /* Heap-allocate each argument for the host */
175:     JSValue **argv_ptrs = NULL;
176:     if (argc > 0) {
177:         argv_ptrs = (JSValue **)malloc(sizeof(JSValue *) * argc);
178:         for (int i = 0; i < argc; i++) {
179:             argv_ptrs[i] = jsvalue_to_heap(JS_DupValue(ctx, argv[i]));
180:         }
181:     }
182: 
183:     /* Call into the host */
184:     JSValue *result_ptr = host_call(name, (int)name_len, this_ptr, argc, argv_ptrs);
185: 
186:     JS_FreeCString(ctx, name);
187: 
188:     /* Extract and dup the result, then free the pointer.
189:        NULL means the host threw an exception (via qjs_throw). */
190:     JSValue result;
191:     if (result_ptr) {
192:         result = JS_DupValue(ctx, *result_ptr);
193:         JS_FreeValue(ctx, *result_ptr);
194:         free(result_ptr);
195:     } else {
196:         result = JS_EXCEPTION;
197:     }
198: 
199:     /* Free the this_ptr (was dup'd for host) */
200:     JS_FreeValue(ctx, *this_ptr);
201:     free(this_ptr);
202: 
203:     /* Free the argv pointers (were dup'd for host) */
204:     if (argv_ptrs) {
205:         for (int i = 0; i < argc; i++) {
206:             JS_FreeValue(ctx, *argv_ptrs[i]);
207:             free(argv_ptrs[i]);
208:         }
209:         free(argv_ptrs);
210:     }
211: 
212:     return result;
213: }
