215: /* ---- Timezone support ---- */
216: 
217: /*
218:  * Imported from the host environment. Called when the WASI libc needs to
219:  * convert a time to local time. Receives seconds since epoch (split into
220:  * hi/lo i32 halves), returns the timezone offset in seconds (e.g. -28800
221:  * for UTC-8).
222:  *
223:  * This overrides the WASI libc stub `__secs_to_zone()` via the linker
224:  * --wrap flag. Calls to `__secs_to_zone` are redirected here.
225:  */
226: __attribute__((import_module("env"), import_name("host_get_timezone_offset")))
227: extern int host_get_timezone_offset(int hi, unsigned int lo);
228: 
229: extern const char __utc[];
230: 
231: void __wrap___secs_to_zone(long long t, int local, int *isdst, int *offset,
232:                            long *oppoff, const char **zonename)
233: {
234:     int off = host_get_timezone_offset((int)(t >> 32), (unsigned int)t);
235:     if (isdst) *isdst = 0;
236:     if (offset) *offset = off;
237:     if (oppoff) *oppoff = 0;
238:     if (zonename) *zonename = off == 0 ? __utc : "LMT";
239: }
