250: /* Intrinsic bitmask flags — must match the TypeScript Intrinsics constants */
251: #define QJS_INTRINSIC_DATE           (1 << 0)
252: #define QJS_INTRINSIC_EVAL           (1 << 1)
253: #define QJS_INTRINSIC_REGEXP         (1 << 2)
254: #define QJS_INTRINSIC_JSON           (1 << 3)
255: #define QJS_INTRINSIC_PROXY          (1 << 4)
256: #define QJS_INTRINSIC_MAP_SET        (1 << 5)
257: #define QJS_INTRINSIC_TYPED_ARRAYS   (1 << 6)
258: #define QJS_INTRINSIC_PROMISE        (1 << 7)
259: #define QJS_INTRINSIC_BIG_INT        (1 << 8)
260: #define QJS_INTRINSIC_WEAK_REF       (1 << 9)
261: #define QJS_INTRINSIC_PERFORMANCE    (1 << 10)
262: #define QJS_INTRINSIC_DOM_EXCEPTION  (1 << 11)
263: #define QJS_INTRINSIC_ATOB_BTOA      (1 << 12)
264: 
265: /* All intrinsics enabled (same as JS_NewContext) */
266: #define QJS_INTRINSIC_ALL 0xFFFFFFFF
267: 
268: __attribute__((export_name("qjs_init")))
269: int qjs_init(void) {
270:     if (rt) return -1; /* already initialized */
271: 
272:     rt = JS_NewRuntime();
273:     if (!rt) return -1;
274: 
275:     ctx = JS_NewContext(rt);
276:     if (!ctx) {
277:         JS_FreeRuntime(rt);
278:         rt = NULL;
279:         return -1;
280:     }
281: 
282:     return 0;
283: }
284: 
285: /*
286:  * Initialize with selective intrinsics. Pass QJS_INTRINSIC_ALL for all
287:  * intrinsics (same as qjs_init), or a bitmask of QJS_INTRINSIC_* flags
288:  * to create a minimal context.
289:  *
290:  * Note: BaseObjects is always included — it provides fundamental types
291:  * (Object, Array, Number, String, etc.) without which nothing works.
292:  */
293: __attribute__((export_name("qjs_init2")))
294: int qjs_init2(unsigned int intrinsics) {
295:     if (rt) return -1; /* already initialized */
296: 
297:     rt = JS_NewRuntime();
298:     if (!rt) return -1;
299: 
300:     if (intrinsics == QJS_INTRINSIC_ALL) {
301:         ctx = JS_NewContext(rt);
302:     } else {
303:         ctx = JS_NewContextRaw(rt);
304:         if (!ctx) {
305:             JS_FreeRuntime(rt);
306:             rt = NULL;
307:             return -1;
308:         }
309:         /* BaseObjects is always required */
310:         JS_AddIntrinsicBaseObjects(ctx);
311:         if (intrinsics & QJS_INTRINSIC_DATE)          JS_AddIntrinsicDate(ctx);
312:         if (intrinsics & QJS_INTRINSIC_EVAL)          JS_AddIntrinsicEval(ctx);
313:         if (intrinsics & QJS_INTRINSIC_REGEXP) {
314:             JS_AddIntrinsicRegExpCompiler(ctx);
315:             JS_AddIntrinsicRegExp(ctx);
316:         }
317:         if (intrinsics & QJS_INTRINSIC_JSON)          JS_AddIntrinsicJSON(ctx);
318:         if (intrinsics & QJS_INTRINSIC_PROXY)         JS_AddIntrinsicProxy(ctx);
319:         if (intrinsics & QJS_INTRINSIC_MAP_SET)        JS_AddIntrinsicMapSet(ctx);
320:         if (intrinsics & QJS_INTRINSIC_TYPED_ARRAYS)   JS_AddIntrinsicTypedArrays(ctx);
321:         if (intrinsics & QJS_INTRINSIC_PROMISE)        JS_AddIntrinsicPromise(ctx);
322:         if (intrinsics & QJS_INTRINSIC_BIG_INT)        JS_AddIntrinsicBigInt(ctx);
323:         if (intrinsics & QJS_INTRINSIC_WEAK_REF)       JS_AddIntrinsicWeakRef(ctx);
324:         if (intrinsics & QJS_INTRINSIC_PERFORMANCE)    JS_AddPerformance(ctx);
325:         if (intrinsics & QJS_INTRINSIC_DOM_EXCEPTION)  JS_AddIntrinsicDOMException(ctx);
326:         /* JS_AddIntrinsicAToB also adds DOMException if not already present. */
327:         if (intrinsics & QJS_INTRINSIC_ATOB_BTOA)      JS_AddIntrinsicAToB(ctx);
328:     }
329: 
330:     if (!ctx) {
331:         JS_FreeRuntime(rt);
332:         rt = NULL;
333:         return -1;
334:     }
335: 
336:     return 0;
337: }
