453:     if (ctx) {
454:         /* Run GC to collect any cycles before freeing the context */
455:         if (rt) JS_RunGC(rt);
456:         JS_FreeContext(ctx);
457:         ctx = NULL;
458:     }
459:     if (rt) {
460:         JS_FreeRuntime(rt);
461:         rt = NULL;
462:     }
463: }
